const event = $input.first().json;
const msg = (event.messages || [])[0] || {};
let text = (msg.text && msg.text.body) ? String(msg.text.body).trim() : '';
if (!text) {
  return [];
}
const from = msg.from || (event.contacts && event.contacts[0] && event.contacts[0].wa_id) || '';
const groupId = msg.group_id || (event.metadata && event.metadata.group_id) || '';
const chatKind = groupId ? 'group' : 'dm';
let department = chatKind === 'group' ? 'community' : 'growth';
const commands = [
  { re: /^(?:\/community|\/cm)\b\s*/i, dest: 'community' },
  { re: /^\/ops\b\s*/i, dest: 'internal-ops' },
  { re: /^\/validate\b\s*/i, dest: 'product-dev' },
  { re: /^\/growth\b\s*/i, dest: 'growth' }
];
for (const cmd of commands) {
  if (cmd.re.test(text)) {
    department = cmd.dest;
    text = text.replace(cmd.re, '').trim();
    break;
  }
}
if (!text) {
  text = department === 'community'
    ? 'Welcome this person and ask how you can help in the community.'
    : 'Greet the person and ask how you can help.';
}
const context_data = {
  channel: 'whatsapp',
  chat_kind: chatKind,
  department,
  from,
  wa_id: (event.contacts && event.contacts[0] && event.contacts[0].wa_id) || from,
  phone_number_id: (event.metadata && event.metadata.phone_number_id) || '1353516234507857'
};
if (groupId) {
  context_data.group_id = groupId;
}
return [{ json: { department, task_description: text, context_data } }];

const worker = $('Call department').item.json;
const ctx = $('Prepare task').item.json.context_data;
let text = String(worker.output_text || 'Sorry, I could not complete that.');
text = text.replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();
let zohoNote = '';
if ($json.expense && $json.expense.expense_id) {
  zohoNote = '\n\nRecorded in Zoho Books as expense ' + $json.expense.expense_id + '.';
} else if ($json.code && $json.message) {
  zohoNote = '\n\nZoho Books: ' + String($json.message);
} else if ($json.error) {
  const err = $json.error;
  zohoNote = '\n\nZoho Books: ' + String(err.message || JSON.stringify(err));
}
text = (text + zohoNote).trim();
if (text.length > 4000) {
  text = text.slice(0, 3990) + '…';
}
return [{
  json: {
    text,
    to: ctx.from,
    phoneNumberId: ctx.phone_number_id,
    status: worker.status || 'failed',
    department: ctx.department || 'growth'
  }
}];

const ORG_ID = '939049468';
const PAID_THROUGH = '1300646000000000361'; // Petty Cash
const DEFAULT_EXPENSE = '1300646000000000460'; // Other Expenses
const ACCOUNTS = [
  { id: '1300646000000000400', keys: ['office supplies', 'stationery', 'printer', 'paper'] },
  { id: '1300646000000000403', keys: ['advertis', 'marketing', 'ads', 'boost'] },
  { id: '1300646000000032023', keys: ['lodging', 'hotel', 'airbnb', 'accommodation'] },
  { id: '1300646000000000460', keys: ['other expenses', 'other', 'misc'] },
  { id: '1300646000000035005', keys: ['uncategor'] },
];

function pickAccount(sd) {
  const hay = [sd.zoho_account_name, sd.account_name, sd.category, sd.vendor, sd.description]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  for (const row of ACCOUNTS) {
    if (row.keys.some((k) => hay.includes(k))) {
      return row.id;
    }
  }
  return DEFAULT_EXPENSE;
}

function lagosDate(raw) {
  if (raw && /^\d{4}-\d{2}-\d{2}/.test(String(raw))) {
    return String(raw).slice(0, 10);
  }
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Lagos' }).format(new Date());
}

const worker = $input.first().json;
const prep = $('Prepare task').item.json;
const sd = worker.structured_data || {};
const amount = Number(sd.amount);
const task = String(sd.task_type || '').toLowerCase();
const recordFlag = sd.record_expense === true || sd.record_expense === 'true';
const record_zoho = prep.department === 'internal-ops'
  && worker.status === 'success'
  && task === 'accounts'
  && recordFlag
  && Number.isFinite(amount)
  && amount > 0;

const vendor = String(sd.vendor || sd.vendor_name || '').trim();
const descParts = [vendor, sd.description || prep.task_description].filter(Boolean);
let description = descParts.join(' — ').slice(0, 100);
if (!description) {
  description = 'Ops expense';
}

const zoho_expense = record_zoho ? {
  account_id: pickAccount(sd),
  paid_through_account_id: PAID_THROUGH,
  date: lagosDate(sd.date),
  amount,
  description,
} : null;

if (zoho_expense) {
  const ref = String(sd.reference || sd.reference_number || '').trim().slice(0, 100);
  if (ref) {
    zoho_expense.reference_number = ref;
  }
}

return [{ json: { ...worker, record_zoho, zoho_expense, organization_id: ORG_ID } }];
